-- Run as ayure_migrator after 0000 and SELECT version() pre-flight.
-- PostgreSQL 16+ required. Core gen_random_uuid() needs no pgcrypto extension.
-- No sequences are used: UUID PK is generated by gen_random_uuid().
-- If a sequence-backed default is added later, grant the runtime sequence USAGE explicitly.
BEGIN;
CREATE TABLE public.ayure_leads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  role text NOT NULL CHECK (role IN ('buyer', 'owner', 'investor', 'operator', 'service_provider')),
  name text NOT NULL CHECK (length(btrim(name)) BETWEEN 2 AND 120),
  email text NOT NULL CHECK (length(email) <= 254 AND email = lower(btrim(email))),
  goal text NOT NULL CHECK (length(btrim(goal)) BETWEEN 8 AND 2000),
  receipt text NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'received'
    CHECK (status IN ('received', 'reviewed', 'contacted', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ayure_leads_created_at_idx ON public.ayure_leads (created_at DESC);
CREATE INDEX ayure_leads_status_created_at_idx ON public.ayure_leads (status, created_at DESC);

CREATE FUNCTION public.ayure_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END
$function$;
CREATE TRIGGER ayure_leads_updated_at
BEFORE UPDATE ON public.ayure_leads FOR EACH ROW
EXECUTE FUNCTION public.ayure_set_updated_at();

-- Column INSERT is narrower than table-wide INSERT; defaults supply id/status/timestamps.
GRANT INSERT (role, name, email, goal, receipt) ON public.ayure_leads TO ayure_app;
-- RETURNING requires SELECT for returned columns. NO SELECT on id or PII.
-- This is column scoped, NOT row scoped: receipts/status/dates for all rows are readable.
GRANT SELECT (receipt, status, created_at) ON public.ayure_leads TO ayure_app;
COMMIT;
